tests:
test({ sr: 'godina deljiva sa 4 je prestupna', en: 'a year divisible by 4 is a leap year' }, () => {
  expect(isLeapYear(2024)).toBe(true);
});
test({ sr: 'godina koja nije deljiva sa 4 nije prestupna', en: 'a year not divisible by 4 is not a leap year' }, () => {
  expect(isLeapYear(2023)).toBe(false);
});
test({ sr: 'vek koji nije deljiv sa 400 nije prestupan', en: 'a century not divisible by 400 is not a leap year' }, () => {
  expect(isLeapYear(1900)).toBe(false);
});

